def test_edge_cases(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


def test_parse_outputs():
    assert parse("") == []
    assert parse("AZYUK2A") == []
    assert parse("Answer: €$%^&*()123.45") == [123.45]
    assert parse(r"$\frac{1}{2}$") == [sympy.Rational(1, 2)]
    assert float(parse("$0.5$")[0]) == pytest.approx(0.5)


def test_verify_parse_basic():
    gold = parse(r"$\frac{1}{2}$")
    answer = parse("$0.5$")
    assert verify(gold, answer)


@pytest.mark.timeout
def test_parse_expr_timeout():
    with patch("math_verify.parser.parse_expr", lambda *args, **kwargs: time.sleep(5)):
        assert parse("1+1", parsing_timeout=1, extraction_mode="first_match", fallback_mode="no_fallback") == []


@pytest.mark.timeout
def test_latex2sympy_timeout():
    with patch("math_verify.parser.latex2sympy", lambda *args, **kwargs: time.sleep(5)):
        assert parse("$1+1$", parsing_timeout=1, extraction_mode="first_match", fallback_mode="no_fallback") == []


@pytest.mark.timeout
def test_verify_timeout():
    gold = parse("1+1")
    answer = parse("1+1")
    with patch("math_verify.grader.sympy_expr_eq", lambda *args, **kwargs: time.sleep(5)):
        assert verify(gold, answer, timeout_seconds=1) is False


def test_string_extraction():
    assert parse("The answer is A.", [StringExtractionConfig(lowercase=False)]) == ["A", "A"]
    assert parse("The answer is A.", [StringExtractionConfig(lowercase=True)]) == ["a", "A"]
    assert parse("The answer is U.", [StringExtractionConfig(strings=("U",))]) == ["u", "U"]
    assert parse("No valid answer here", [StringExtractionConfig()]) == []


def test_boxed_priority():
    assert parse(
        "final answer is $9999$, \\boxed{1}",
        [LatexExtractionConfig(boxed_match_priority=0)],
    ) == [1]
    assert parse(
        "final answer is $9999$, \\boxed{1}",
        [LatexExtractionConfig(boxed_match_priority=100)],
    ) == [9999]
    assert parse(
        "\\boxed{1}",
        [LatexExtractionConfig(boxed_match_priority=-1)],
        fallback_mode="no_fallback",
    ) == []

from tests.test_all import compare_strings


def test_boxed_set_with_units():
    assert compare_strings(r"$\boxed{35 cm} ++++++ \boxed{4}$", r"${35 cm,4}$") == 1


def test_boxed_leading_zeros():
    assert compare_strings(r"\boxed{004}", r"$004$") == 1


def test_boxed_plain_number():
    assert compare_strings(r"\boxed{840}", r"$840$") == 1
